package com.paymentplatform.distribution_service.domain;
import com.paymentplatform.distribution_service.api.ApiException;
import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;import java.util.*;import java.time.*;
@Service public class CashStore {
 private final JdbcTemplate jdbc;private final ObjectMapper json;public CashStore(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}
 public record Context(UUID customer,UUID walletAccount,UUID settlementAccount,UUID reservation,Instant expiresAt){}
 public record Row(UUID id,String maker,String checker,UUID wallet,String direction,long amount,String evidence,String state,Context context,UUID journal){}
 private Row read(java.sql.ResultSet r)throws java.sql.SQLException{String context=r.getString("context");return new Row(r.getObject("id",UUID.class),r.getString("maker"),r.getString("checker"),r.getObject("wallet_id",UUID.class),r.getString("direction"),r.getLong("amount"),r.getString("evidence"),r.getString("state"),context==null?null:json.readValue(context,Context.class),r.getObject("journal_id",UUID.class));}
 public Row get(String tenant,UUID id){return jdbc.query("SELECT * FROM cash_operations WHERE integrator_id=? AND id=?",(r,n)->read(r),tenant,id).stream().findFirst().orElseThrow(()->error(HttpStatus.NOT_FOUND,"CASH_OPERATION_NOT_FOUND"));}
 @Transactional(timeout=10) public Row begin(String tenant,String actor,String key,CashWorkflow.Request request){
  jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(org.springframework.jdbc.core.RowCallbackHandler)r->{},"cash:"+tenant+":"+key);
  String hash=RequestKeys.hash(json.writeValueAsString(List.of(request.walletId(),request.direction(),request.amount(),request.evidence())),actor);
  var old=jdbc.query("SELECT id,fingerprint FROM cash_operations WHERE integrator_id=? AND idempotency_key=?",(r,n)->List.of(r.getString(1),r.getString(2)),tenant,key);
  if(!old.isEmpty()){if(!old.getFirst().get(1).equals(hash))throw error(HttpStatus.CONFLICT,"CASH_IDEMPOTENCY_CONFLICT");return get(tenant,UUID.fromString(old.getFirst().getFirst()));}
  UUID id=UUID.randomUUID();int inserted=jdbc.update("INSERT INTO cash_operations(id,integrator_id,idempotency_key,fingerprint,maker,wallet_id,direction,amount,evidence,state) VALUES (?,?,?,?,?,?,?,?,?,'NEW') ON CONFLICT DO NOTHING",id,tenant,key,hash,actor,request.walletId(),request.direction(),request.amount(),request.evidence());if(inserted!=1)throw error(HttpStatus.CONFLICT,"EVIDENCE_ALREADY_USED");return get(tenant,id);
 }
 @Transactional(timeout=10) public Row approve(String tenant,String actor,UUID id){var rows=jdbc.query("SELECT * FROM cash_operations WHERE integrator_id=? AND id=? FOR UPDATE",(r,n)->read(r),tenant,id);if(rows.isEmpty())throw error(HttpStatus.NOT_FOUND,"CASH_OPERATION_NOT_FOUND");var row=rows.getFirst();if(row.maker().equals(actor))throw error(HttpStatus.FORBIDDEN,"INDEPENDENT_CHECKER_REQUIRED");if(row.checker()!=null){if(!row.checker().equals(actor))throw error(HttpStatus.CONFLICT,"CHECKER_CONFLICT");return row;}if(!row.state().equals("REQUESTED"))throw error(HttpStatus.CONFLICT,"CASH_STATE_CONFLICT");jdbc.update("UPDATE cash_operations SET checker=?,state='APPROVED' WHERE integrator_id=? AND id=?",actor,tenant,id);return get(tenant,id);}
 public UUID claim(String tenant,UUID id){UUID lease=UUID.randomUUID();return jdbc.update("UPDATE cash_operations SET lease_token=?,lease_until=clock_timestamp()+INTERVAL '120 seconds' WHERE integrator_id=? AND id=? AND (lease_until IS NULL OR lease_until<clock_timestamp())",lease,tenant,id)==1?lease:null;}
 public Row save(String tenant,UUID id,UUID lease,String state,Context context,UUID journal){int count=jdbc.update("UPDATE cash_operations SET state=?,context=?::jsonb,journal_id=? WHERE integrator_id=? AND id=? AND lease_token=? AND lease_until>clock_timestamp()",state,json.writeValueAsString(context),journal,tenant,id,lease);if(count!=1)throw error(HttpStatus.CONFLICT,"LEASE_LOST");return get(tenant,id);}
 public void release(String tenant,UUID id,UUID lease){jdbc.update("UPDATE cash_operations SET lease_token=NULL,lease_until=NULL WHERE integrator_id=? AND id=? AND lease_token=?",tenant,id,lease);}
 @Transactional(timeout=10) public Row disburse(String tenant,String actor,UUID id){var row=get(tenant,id);if(!row.maker().equals(actor))throw error(HttpStatus.FORBIDDEN,"ORIGINAL_CASHIER_REQUIRED");if(!row.direction().equals("OUT")||!Set.of("ACCOUNTED","DISBURSED").contains(row.state()))throw error(HttpStatus.CONFLICT,"ACCOUNTING_REQUIRED");jdbc.update("UPDATE cash_operations SET state='DISBURSED',disbursed_at=COALESCE(disbursed_at,clock_timestamp()) WHERE integrator_id=? AND id=? AND state='ACCOUNTED'",tenant,id);return get(tenant,id);}
 public static ApiException error(HttpStatus s,String code){return new ApiException(s,code,"The controlled cash operation cannot be accepted.");}
}
